import Image from 'next/image';
import Link from 'next/link';

import styles from './styles.module.scss';

export default function DesktopHeader() {
  return <div className={styles['desktop-header']}>
    <div className={styles['desktop-header__logo']}>
      <Image src='/logo-black.avif' alt='AMBILUX ARCHITECTS' fill/>
    </div>

    <div className={styles['desktop-header__navigation']}>
      <Link className={styles['desktop-header__navigation-item']} href='/'>Главная</Link>
      <Link className={styles['desktop-header__navigation-item']} href='/about'>О нас</Link>
      <Link className={styles['desktop-header__navigation-item']} href='/projects'>Проекты</Link>
      <Link className={styles['desktop-header__navigation-item']} href='/vacancies'>Команда</Link>
      <Link className={styles['desktop-header__navigation-item']} href='/contacts'>Контакты</Link>
    </div>
  </div>
}
